from typing import Any, Optional, TypedDict

class FraudState(TypedDict, total=False):
    """
    Shared state for the credit card fraud investigation workflow.

    Each LangGraph node reads the information it needs
    and returns updates to this shared state.
    """

    # Input transaction
    transaction: dict[str, Any]

    # ML prediction from XGBoost
    prediction: dict[str, Any]

    # SHAP feature explanations
    shap_explanation: dict[str, Any]

    # Investigation generated by the LLM
    investigation: str

    # Retrieved fraud policies (RAG integration in Phase 5)
    policy_context: str

    # Final investigation report
    final_report: dict[str, Any]

    # Workflow tracking
    status: str
    error: Optional[str]
